/**
 * PptxGenJS: Slide Class
 */

import { CHART_NAME, SHAPE_NAME } from './core-enums'
import {
	AddSlideProps,
	BackgroundProps,
	AvatarProps,
	BadgeProps,
	CalloutProps,
	CardProps,
	CommentProps,
	SeparatorProps,
	GroupProps,
	HeaderFooterProps,
	HexColor,
	IChartMulti,
	IChartOpts,
	IChartOptsLib,
	IOptsChartData,
	ISlideObject,
	ISlideRel,
	ISlideRelChart,
	ISlideRelMedia,
	ImageProps,
	InkProps,
	SmartArtProps,
	MediaProps,
	NoteParagraph,
	PresLayout,
	PresSlide,
	ShapeProps,
	SlideGroup,
	SlideLayout,
	SlideNumberProps,
	TableProps,
	TableRow,
	TextProps,
	TextPropsOptions,
	TransitionProps,
} from './core-interfaces'
import * as genObj from './gen-objects'

export default class Slide {
	private readonly _setSlideNum: (value: SlideNumberProps) => void

	public addSlide: (options?: AddSlideProps) => PresSlide
	public getSlide: (slideNum: number) => PresSlide
	public _name: string
	public _presLayout: PresLayout
	public _rels: ISlideRel[]
	public _relsChart: ISlideRelChart[]
	public _relsMedia: ISlideRelMedia[]
	public _rId: number
	public _slideId: number
	public _slideLayout: SlideLayout
	public _slideNum: number
	public _slideNumberProps: SlideNumberProps
	public _headerFooter: HeaderFooterProps
	public _slideObjects: ISlideObject[]
	public _comments: CommentProps[]
	public _ink: Array<{ strokes: number[][][], color?: HexColor, width?: number, _rId: number, _target: string }>
	public _diagram: Array<{ layout: 'list' | 'process', items: string[], color?: HexColor, w: number, h: number, _id: string, _dataRid: number, _layoutRid: number, _quickStyleRid: number, _colorsRid: number, _drawingRid: number }>
	public _newAutoPagedSlides: PresSlide[]

	constructor(params: {
		addSlide: (options?: AddSlideProps) => PresSlide
		getSlide: (slideNum: number) => PresSlide
		presLayout: PresLayout
		setSlideNum: (value: SlideNumberProps) => void
		slideId: number
		slideRId: number
		slideNumber: number
		slideLayout?: SlideLayout
	}) {
		this.addSlide = params.addSlide
		this.getSlide = params.getSlide
		this._name = `Slide ${params.slideNumber}`
		this._presLayout = params.presLayout
		this._rId = params.slideRId
		this._rels = []
		this._relsChart = []
		this._relsMedia = []
		this._setSlideNum = params.setSlideNum
		this._slideId = params.slideId
		this._slideLayout = params.slideLayout || null
		this._slideNum = params.slideNumber
		this._slideObjects = []
		/** NOTE: Slide Numbers: In order for Slide Numbers to function they need to be in all 3 files: master/layout/slide
		 * `defineSlideMaster` and `addNewSlide.slideNumber` will add {slideNumber} to `this.masterSlide` and `this.slideLayouts`
		 * so, lastly, add to the Slide now.
		 */
		this._slideNumberProps = this._slideLayout?._slideNumberProps ? this._slideLayout._slideNumberProps : null
		/** NOTE: Per-slide header/footer override. `<p:hf>` is invalid on `CT_Slide`, so a per-slide
		 * override is purely placeholder-presence (footer/date `<p:sp>`) in the slide's own `<p:spTree>`,
		 * emitted by `slideObjectToXml` STEP-4b when set. Default `null` keeps slides byte-identical.
		 */
		this._headerFooter = null
		/** NOTE: Review comments (default `[]`). Empty → no comment parts/rels/overrides → byte-identical. */
		this._comments = []
		/** NOTE: Ink annotations (default `[]`). Empty → no ink parts/rels/overrides/contentPart → byte-identical. */
		this._ink = []
		/** NOTE: SmartArt diagrams (default `[]`). Empty → no diagram parts/rels/overrides/graphicFrame → byte-identical. */
		this._diagram = []
	}

	/**
	 * Background color
	 * @type {string|BackgroundProps}
	 * @deprecated in v3.3.0 - use `background` instead
	 */
	private _bkgd: string | BackgroundProps
	public set bkgd(value: string | BackgroundProps) {
		this._bkgd = value
		if (!this._background || !this._background.color) {
			if (!this._background) this._background = {}
			if (typeof value === 'string') this._background.color = value
		}
	}

	public get bkgd(): string | BackgroundProps {
		return this._bkgd
	}

	/**
	 * Background color or image
	 * @type {BackgroundProps}
	 * @example solid color `background: { color:'FF0000' }`
	 * @example color+trans `background: { color:'FF0000', transparency:0.5 }`
	 * @example base64 `background: { data:'image/png;base64,ABC[...]123' }`
	 * @example url `background: { path:'https://some.url/image.jpg'}`
	 * @since v3.3.0
	 */
	private _background: BackgroundProps
	public set background(props: BackgroundProps) {
		this._background = props
		// Add background (image data/path must be captured before `exportPresentation()` is called)
		if (props) genObj.addBackgroundDefinition(props, this)
	}

	public get background(): BackgroundProps {
		return this._background
	}

	/**
	 * Default font color
	 * @type {HexColor}
	 */
	private _color: HexColor
	public set color(value: HexColor) {
		this._color = value
	}

	public get color(): HexColor {
		return this._color
	}

	/**
	 * @type {boolean}
	 */
	private _hidden: boolean
	public set hidden(value: boolean) {
		this._hidden = value
	}

	public get hidden(): boolean {
		return this._hidden
	}

	/**
	 * Slide transition (entrance effect applied when navigating to this slide)
	 * @type {TransitionProps}
	 */
	private _transition: TransitionProps
	public set transition(value: TransitionProps) {
		this._transition = value
	}

	public get transition(): TransitionProps {
		return this._transition
	}

	/**
	 * @type {SlideNumberProps}
	 */
	public set slideNumber(value: SlideNumberProps) {
		// NOTE: Slide Numbers: In order for Slide Numbers to function they need to be in all 3 files: master/layout/slide
		this._slideNumberProps = value
		this._setSlideNum(value)
	}

	public get slideNumber(): SlideNumberProps {
		return this._slideNumberProps
	}

	/**
	 * Per-slide header/footer override (footer text + date/time placeholders).
	 * NOTE: `<p:hf>` is not valid on `CT_Slide`, so the `slideNumber` toggle is a no-op here
	 * (use `slideNumber` for the slide-number placeholder); per-slide scope is footer + dateTime only.
	 * @type {HeaderFooterProps}
	 * @example slide.headerFooter = { footer: 'Confidential', dateTime: { value: 'Q1 2026' } }
	 */
	public set headerFooter(value: HeaderFooterProps) {
		this._headerFooter = value
	}

	public get headerFooter(): HeaderFooterProps {
		return this._headerFooter
	}

	public get newAutoPagedSlides(): PresSlide[] {
		return this._newAutoPagedSlides
	}

	/**
	 * Add chart to Slide
	 * @param {CHART_NAME|IChartMulti[]} type - chart type
	 * @param {object[]} data - data object
	 * @param {IChartOpts} options - chart options
	 * @return {Slide} this Slide
	 */
	addChart(type: CHART_NAME | IChartMulti[], data: IOptsChartData[], options?: IChartOpts): Slide {
		// FUTURE: TODO-VERSION-4: Remove first arg - only take data and opts, with "type" required on opts
		// Set `_type` on IChartOptsLib as its what is used as object is passed around
		const optionsWithType: IChartOptsLib = options || {}
		optionsWithType._type = type
		genObj.addChartDefinition(this, type, data, options)
		return this
	}

	/**
	 * Add image to Slide
	 * @param {ImageProps} options - image options
	 * @return {Slide} this Slide
	 */
	addImage(options: ImageProps): Slide {
		genObj.addImageDefinition(this, options)
		return this
	}

	/**
	 * Add media (audio/video) to Slide
	 * @param {MediaProps} options - media options
	 * @return {Slide} this Slide
	 */
	addMedia(options: MediaProps): Slide {
		genObj.addMediaDefinition(this, options)
		return this
	}

	/**
	 * Add speaker notes to Slide
	 * @docs https://gitbrent.github.io/PptxGenJS/docs/speaker-notes.html
	 * @param {string | NoteParagraph[]} notes - notes to add to slide; a string is a single paragraph, an array authors structured talking-points (bullets + indent levels)
	 * @return {Slide} this Slide
	 */
	addNotes(notes: string | NoteParagraph[]): Slide {
		genObj.addNotesDefinition(this, notes)
		return this
	}

	/**
	 * Add a review comment to Slide.
	 * Emits a `<p:cm>` into the slide's `ppt/comments/comment{N}.xml` part; the author is
	 * resolved/deduped into the shared `ppt/commentAuthors.xml`. Default-off when never called.
	 * @param {CommentProps} options - comment author, text, and optional anchor/date
	 * @return {Slide} this Slide
	 */
	addComment(options: CommentProps): Slide {
		genObj.addCommentDefinition(this, options)
		return this
	}

	/**
	 * Add an ink (stylus/handwriting) annotation to Slide.
	 * Emits a per-call `ppt/ink/ink-{N}-{i}.xml` InkML part referenced from the slide's
	 * `<p:spTree>` via a `<p:contentPart r:id>` + slide relationship + Content_Types Override.
	 * Each stroke is an array of `[x, y]` points in inches. Empty/degenerate strokes are dropped;
	 * a call with no valid strokes is a no-op (default-off when never called).
	 * @param {InkProps} options - ink strokes + optional color/width
	 * @return {Slide} this Slide
	 */
	addInk(options: InkProps): Slide {
		genObj.addInkDefinition(this, options)
		return this
	}

	/**
	 * Add a SmartArt/diagram to Slide.
	 * Minimal subset: a flat `items` array rendered as a `list` (vertical) or `process` (horizontal)
	 * diagram. Emits five linked `ppt/diagrams/*N.xml` parts (data/layout/quickStyle/colors/drawing)
	 * + a `<p:graphicFrame>` with `<dgm:relIds>` + slide rels + Content_Types overrides. Empty/invalid
	 * `items` or an unknown `layout` is a no-op (default-off when never called).
	 * @param {SmartArtProps} options - layout + items (+ optional position/color)
	 * @return {Slide} this Slide
	 */
	addSmartArt(options: SmartArtProps): Slide {
		genObj.addSmartArtDefinition(this, options)
		return this
	}

	/**
	 * Add shape to Slide
	 * @param {SHAPE_NAME} shapeName - shape name
	 * @param {ShapeProps} options - shape options
	 * @return {Slide} this Slide
	 */
	addShape(shapeName: SHAPE_NAME, options?: ShapeProps): Slide {
		// NOTE: As of v3.1.0, <script> users are passing the old shape object from the shapes file (orig to the project)
		// But React/TypeScript users are passing the shapeName from an enum, which is a simple string, so lets cast
		// <script./> => `pptx.shapes.RECTANGLE` [string] "rect" ... shapeName['name'] = 'rect'
		// TypeScript => `pptxgen.shapes.RECTANGLE` [string] "rect" ... shapeName = 'rect'
		// let shapeNameDecode = typeof shapeName === 'object' && shapeName['name'] ? shapeName['name'] : shapeName
		genObj.addShapeDefinition(this, shapeName, options)
		return this
	}

	/**
	 * Add a shape group to Slide (Feature 6).
	 * Returns a group handle whose `addShape()`/`addText()` use coordinates relative to the
	 * group origin; the group emits a `<p:grpSp>` with an absolute `<a:xfrm>` + `chOff`/`chExt`.
	 * @param {GroupProps} options - group position/size options
	 * @return {SlideGroup} group handle exposing `addShape` / `addText`
	 */
	addGroup(options: GroupProps): SlideGroup {
		return genObj.addGroupDefinition(this, options)
	}

	/**
	 * Add a rounded-rectangle callout/badge to Slide (Feature 7).
	 * Sugar over `addShape('roundRect', …)` with centred text and an `adj`
	 * corner-radius derived from `cornerRadius` (inches).
	 * @param {CalloutProps} options - callout options
	 * @return {Slide} this Slide
	 */
	addCallout(options: CalloutProps): Slide {
		genObj.addCalloutDefinition(this, options)
		return this
	}

	/**
	 * Add a structured card (rounded-rect background + optional icon/title/description/badge)
	 * to Slide as a single shape group.
	 * @param {CardProps} options - card options
	 * @return {Slide} this Slide
	 */
	addCard(options: CardProps): Slide {
		genObj.addCardDefinition(this, options)
		return this
	}

	/**
	 * Add an avatar/initials chip (filled ellipse + centred initials) to Slide.
	 * Sugar composing an `ellipse` and a centred text box — no new OOXML.
	 * @param {AvatarProps} options - avatar options
	 * @return {Slide} this Slide
	 */
	addAvatar(options: AvatarProps): Slide {
		genObj.addAvatarDefinition(this, options)
		return this
	}

	/**
	 * Add a badge/pill (rounded-rect or circle + centred label) to Slide.
	 * Sugar composing a `roundRect`/`ellipse` and a centred text box — no new OOXML.
	 * @param {BadgeProps} options - badge options
	 * @return {Slide} this Slide
	 */
	addBadge(options: BadgeProps): Slide {
		genObj.addBadgeDefinition(this, options)
		return this
	}

	/**
	 * Add a thin horizontal/vertical separator rule (a single `rect`) to Slide.
	 * Sugar composing a `rect` with colour/thickness/opacity — no new OOXML.
	 * @param {SeparatorProps} options - separator options
	 * @return {Slide} this Slide
	 */
	addSeparator(options: SeparatorProps): Slide {
		genObj.addSeparatorDefinition(this, options)
		return this
	}

	/**
	 * Add table to Slide
	 * @param {TableRow[]} tableRows - table rows
	 * @param {TableProps} options - table options
	 * @return {Slide} this Slide
	 */
	addTable(tableRows: TableRow[], options?: TableProps): Slide {
		// FUTURE: we pass `this` - we dont need to pass layouts - they can be read from this!
		this._newAutoPagedSlides = genObj.addTableDefinition(this, tableRows, options, this._slideLayout, this._presLayout, this.addSlide, this.getSlide)
		return this
	}

	/**
	 * Add text to Slide
	 * @param {string|TextProps[]} text - text string or complex object
	 * @param {TextPropsOptions} options - text options
	 * @return {Slide} this Slide
	 */
	addText(text: string | TextProps[], options?: TextPropsOptions): Slide {
		const textParam = typeof text === 'string' || typeof text === 'number' ? [{ text, options }] : text
		genObj.addTextDefinition(this, textParam, options, false)
		return this
	}
}
